const CASES=[{"cards": [{"id": 47, "pos": "对方的心情", "rev": false}, {"id": 6, "pos": "自己的状况", "rev": false}, {"id": 15, "pos": "相处方式", "rev": false}, {"id": 18, "pos": "周遭环境", "rev": false}, {"id": 13, "pos": "关系结果", "rev": false}], "cat": "感情", "conclusion": "牌面显示他确有回头意（圣杯骑士），但恶魔＋月亮警告：这段关系的问题一个都没解决。建议先别急着答应复合，用恋人\"选择\"的姿态跟他谈一次——把相处模式、联系频率、底线都谈清楚再说；谈不清，这次复合只是下一轮拉扯的开始。", "id": "c1", "question": "分手三个月了，他偶尔还会联系我，到底还想不想复合？", "scan": "大牌占 4/5，分量很重——这不是\"聊不聊得来\"的小事，是整段关系的课题级转折；花色上圣杯（情）配恶魔（执念）加月亮（恐惧），情绪浓度极高；全正位，局势正在按它自己的方向推进。", "source": "练习案例 · 虚构示意", "spread_id": "s6", "steps": ["对方的心情 · 圣杯骑士：他是真的还有感觉——骑士带着花来，是浪漫和示好；但骑士也代表\"来得快去得也快\"，要看后续行动，别只看姿态。", "自己的状况 · 恋人：你正站在岔路口——选复合还是彻底翻篇，这道选择题其实是你自己要先答的。", "相处方式 · 恶魔：你们的互动模式有执念成分——放不下、反复拉扯；牌提醒你先分清这是爱，还是不甘心。", "周遭环境 · 月亮：外界信息很乱（朋友转述、社交动态脑补），很多\"他好像还想\"可能是月光下的影子，先分清想象和现实。", "关系结果 · 死神：无论复合与否，旧模式必须结束——要么带着新规则重新开始，要么彻底告别，没有\"回到从前\"的选项。"], "title": "复合：他还想回头吗"}, {"cards": [{"id": 7, "pos": "求问者现况", "rev": false}, {"id": 10, "pos": "选甲的近况", "rev": false}, {"id": 0, "pos": "选乙的近况", "rev": false}, {"id": 8, "pos": "选甲的未来", "rev": false}, {"id": 3, "pos": "选乙的未来", "rev": false}], "cat": "事业", "conclusion": "两条路都是顺的（全正位）：留＝稳中带变的慢收益，走＝高波动高回报。建议问自己一个问题：现阶段更想要\"确定性\"还是\"可能性\"？想要可能性，愚人＋女皇的组合值得赌——但入职前先把行业基本功的补课计划列好，别裸跳。", "id": "c2", "question": "现在的公司稳定但没成长，新公司涨薪 30% 但要去陌生行业，该怎么选？", "scan": "大牌 5/5 全满——这是未来两三年的职业方向级选择，值得认真对待；全正位，两条路都走得通，区别只在节奏和代价。", "source": "练习案例 · 虚构示意", "spread_id": "s5", "steps": ["求问者现况 · 战车：你现在的状态是\"拉得动\"——意志和执行力都在线，不缺闯的资本，缺的只是一个方向。", "选甲的近况（留现公司）· 命运之轮：轮子正在转，内部可能有调岗或新项目的机会出现，稳定里藏着变量。", "选乙的近况（去新公司）· 愚人：全新的开始，凭直觉跳出去会有惊喜；但愚人也意味着\"没地图\"——行业陌生是真实成本。", "选甲的未来（留下）· 力量：走的是慢功夫——用耐心驯服现状，一年后你会感谢现在的沉住气，但过程不刺激。", "选乙的未来（去）· 女皇：新土壤能开花结果，付出进入收获期——前提是你熬得过愚人阶段的开荒期。"], "title": "跳槽：留还是走"}, {"cards": [{"id": 1, "pos": "过去", "rev": false}, {"id": 9, "pos": "现在", "rev": false}, {"id": 19, "pos": "未来", "rev": false}], "cat": "学业", "conclusion": "不用换方法，换节奏：把 10 小时拆成\"学—复盘—休息\"的循环，隐士牌明确说抽离一下效率更高。方向没错，坚持到太阳。", "id": "c3", "question": "备考到瓶颈期了，每天学 10 小时但效率很低，要不要换学习方法？", "scan": "全大牌 3/3——这是\"学习观\"层面的课题，不是换个 App 就能解决的；全正位，方向没错，问题在节奏。", "source": "练习案例 · 虚构示意", "spread_id": "s3", "steps": ["过去 · 魔术师：你开局是对的——资料、计划、方法都齐了，万事俱备才走到今天，不是运气。", "现在 · 隐士：瓶颈期的正解是隐士式的\"向内\"：减少输入、增加复盘，把刷题时间分一半给整理错题和复述。", "未来 · 太阳：牌给的是高光结局——但太阳照的是\"持续做对的事\"的人，不是\"熬时长\"的人。"], "title": "考研冲刺：这三个月怎么安排"}, {"cards": [{"id": 11, "pos": "问题现况", "rev": false}, {"id": 15, "pos": "障碍或援助", "rev": true}, {"id": 2, "pos": "理想状况", "rev": false}, {"id": 12, "pos": "本意", "rev": false}, {"id": 20, "pos": "过去状况", "rev": false}, {"id": 16, "pos": "未来状况", "rev": false}, {"id": 33, "pos": "你的现况", "rev": false}, {"id": 14, "pos": "周围环境", "rev": false}, {"id": 17, "pos": "你的愿望", "rev": false}, {"id": 21, "pos": "最后结果", "rev": false}], "cat": "感情", "conclusion": "可以继续，但把节奏交给女祭司：观察代替审判。塔的那一下（发现他真实的样子）迟早会来，提前知道它是\"去幻存真\"而不是\"塌房\"，到时候就不会慌。建议未来两个月多看他处理分歧的方式，少看他说的话。", "id": "c4", "question": "刚认识两个月，他对我很好，但总觉得看不透，能继续投入吗？", "scan": "大牌 9/10——这段关系对你而言是课题级的，牵动很深；恶魔逆＋塔正：藏着一段\"看清真相→结构震动\"的过程；但收尾是星星＋世界，希望和圆满都在，震荡是过程不是结局。", "source": "练习案例 · 虚构示意", "spread_id": "s8", "steps": ["问题现况 · 正义：这段关系目前是公平的——付出和回馈对等，他的好是真实的。", "障碍或援助 · 恶魔逆：好消息——你正在挣脱\"看不透就脑补最坏\"的旧模式，看清的能力在恢复。", "理想状况 · 女祭司：别急着要答案，再观察一阵，你的直觉正在收集信息。", "本意 · 倒吊人：你内心真正想要的不是\"他靠不靠谱\"的判决，而是学会在关系里换位看人。", "过去状况 · 审判：你刚从上一段感情的课题里醒过来，带着新标准在看人——标准高是好事。", "未来状况 · 塔：会有一次\"幻灭\"时刻——可能是发现他不如想象中完美，冲击不小，但这是必经的去幻过程。", "你的现况 · 权杖骑士：你是行动派心态，想快点有个结论——骑士的急躁恰恰是需要按住的部分。", "周围环境 · 节制：朋友们的看法是调和的，没人强烈反对，环境不添乱。", "你的愿望 · 星星：你想要的是\"被温柔以待的确定感\"，这个愿望本身没问题。", "最后结果 · 世界：走完这个认知过程，关系能进入一个完整的新阶段——圆满，但\"新阶段\"不等于\"和最初幻想的一样\"。"], "title": "新恋情：他靠谱吗"}, {"cards": [{"id": 4, "pos": "第一张", "rev": false}, {"id": 5, "pos": "第二张", "rev": true}, {"id": 10, "pos": "第三张", "rev": true}], "cat": "选择", "conclusion": "想走自己的路没错（教皇逆），能力也够（皇帝），但时机不对（命运之轮逆）。建议别 all in，先以最小成本验证——副业或兼职合伙跑三个月，等轮子转上来再下注。", "id": "c5", "question": "有个创业机会找我合伙，但要降薪 all in，值得赌吗？", "scan": "3 张全大牌——人生方向级的问题；教皇逆＋命运之轮逆：现在不是\"天时\"，但\"人和\"（皇帝）是齐的。", "source": "练习案例 · 虚构示意", "spread_id": "s2", "steps": ["第一张 · 皇帝：你手里的牌是秩序和执行力——这是创业最稀缺的素质，你有。", "第二张 · 教皇逆：常规路径（继续打工升职）对你已经没吸引力了，想走自己的路是真实的。", "第三张 · 命运之轮逆：但轮子现在在低谷——行业、时机、资金至少一样还没转到位，all in 的代价会比预想大。"], "title": "创业还是继续打工"}, {"cards": [{"id": 5, "pos": "问题核心", "rev": false}, {"id": 7, "pos": "障碍或短处", "rev": true}, {"id": 8, "pos": "对策", "rev": false}, {"id": 11, "pos": "资源或长处", "rev": false}], "cat": "事业", "conclusion": "赢面在\"稳\"不在\"奇\"：按教皇的路子准备材料（数据＋流程＋结果），用力量的节奏稳住心态。答辩前一周别再加新内容了，战车逆警告：贪多会翻车。", "id": "c6", "question": "下个月升职答辩，竞争对手很强，我该怎么准备才能赢？", "scan": "大牌 4/4——这是\"职业身份\"级的事件；战车逆是唯一的逆位，也是整局的题眼：问题不在能力，在状态。", "source": "练习案例 · 虚构示意", "spread_id": "s4", "steps": ["问题核心 · 教皇：这次答辩看的是\"是否走正道\"——业绩、流程、合规，评委要的是稳妥可信，不是花活。", "障碍或短处 · 战车逆：你现在有点被焦虑牵着走——准备时东一榔头西一棒子，方向盘打滑。", "对策 · 力量：别跟焦虑硬碰硬——把准备拆成每天一小块，用耐心驯服它；答辩现场温和坚定比气场全开更打动人。", "资源或长处 · 正义：你过去的成绩是实打实的，因果不亏待人——把\"做了什么、带来什么结果\"一条条摆出来，就是最强的牌。"], "title": "升职答辩：怎么准备"}, {"cards": [{"id": 12, "pos": "指引", "rev": true}], "cat": "综合", "conclusion": "今天先按兵不动，把方案再打磨一轮。等对方主动释放信号（或换个他状态好的日子），倒吊人转正时再去，一次谈成。", "id": "c7", "question": "有个合作想今天去谈，但心里没底，今天去合适吗？", "scan": "单张牌，直指核心——逆位的倒吊人是今天的全部信息：别硬来。", "source": "练习案例 · 虚构示意", "spread_id": "s1", "steps": ["指引 · 倒吊人逆：今天不适合\"主动推进\"——逆位说的是\"越挣扎越糟\"：对方现在没在听的频道上，去了也谈不出结果，反而显得急。"], "title": "单牌：今天适合主动推进那件事吗"}, {"cards": [{"id": 2, "pos": "我的心态", "rev": true}, {"id": 38, "pos": "对方的心态", "rev": false}, {"id": 6, "pos": "过去", "rev": false}, {"id": 18, "pos": "现在", "rev": true}, {"id": 21, "pos": "未来发展", "rev": true}, {"id": 14, "pos": "环境", "rev": false}], "cat": "感情", "conclusion": "牌没有判死刑（世界逆≠世界碎），但女祭司逆点名了你：先诚实面对自己到底还想不想要。建议别在微信里谈，约一次见面，把\"你还想继续吗\"摆到桌面上——答案你们俩都有，只是都没说。", "id": "c8", "question": "异地一年了，见面越来越少，感觉在慢慢变淡，还要坚持吗？", "scan": "大牌 5/6——感情课题，分量不轻；月亮逆是转折点：之前很多\"变淡了\"的感觉，正在被证实或证伪；世界逆收尾：差一口气，但\"差一口气\"本身也是答案的一部分。", "source": "练习案例 · 虚构示意", "spread_id": "s7", "steps": ["我的心态 · 女祭司逆：你其实已经有答案了，只是不愿听——逆位说你在用忙碌盖住直觉。", "对方的心态 · 圣杯三：他在那边的生活是热闹的（朋友、社交），不是不爱，是\"异地\"这件事在他生活里的权重在下降。", "过去 · 恋人：你们是认真选择过彼此的，这段感情的起点是真的。", "现在 · 月亮逆：好消息——迷雾在散，你会越来越看清这段关系的真实样子，不再靠脑补。", "未来发展 · 世界逆：按现在这样下去，圆满差一口气——不是没可能，是需要有人先把\"那口气\"补上（一次长谈、一次见面、一个决定）。", "环境 · 节制：外部没有阻力，没人反对、没有第三者，问题纯粹在你们两人之间。"], "title": "异地恋：这段关系走得下去吗"}, {"cards": [{"id": 4, "pos": "问题核心", "rev": true}, {"id": 7, "pos": "障碍或短处", "rev": true}, {"id": 1, "pos": "对策", "rev": false}, {"id": 3, "pos": "资源或长处", "rev": false}], "cat": "事业", "conclusion": "别立威，立功。皇帝逆＋女皇正的组合拳是：收起\"我是领导\"的架子（皇帝逆），用\"跟着我有肉吃\"带团队（女皇＋魔术师）。三个月后，他们服的是你的战绩，不是你的职位。", "id": "c9", "question": "刚升管理岗，团队里几个老员工不太服我，怎么立威又不伤和气？", "scan": "大牌 4/4——这是\"领导力\"课题；皇帝逆＋战车逆连在一起：问题不在他们刺头，在你\"想立威\"这个念头本身用力过猛了。", "source": "练习案例 · 虚构示意", "spread_id": "s4", "steps": ["问题核心 · 皇帝逆：你现在的模式是\"怕管不住所以先绷紧\"——逆位皇帝警告：越用力证明权威，越容易变成大家眼里的\"官威\"。", "障碍或短处 · 战车逆：方向盘在打滑——你想快点出成绩证明自己，反而让团队觉得你只顾自己。", "对策 · 魔术师：你手里其实什么都有——专业能力、老板的信任、对业务的理解。魔术师的做法是\"展示\"不是\"证明\"：带着他们打一场胜仗，比开十次会管用。", "资源或长处 · 女皇：你真正的武器是滋养——多给资源、多给露脸机会，老员工要的是被尊重，不是被管。"], "title": "带团队：怎么管住几个刺头"}, {"cards": [{"id": 10, "pos": "过去", "rev": true}, {"id": 12, "pos": "现在", "rev": false}, {"id": 17, "pos": "未来", "rev": false}], "cat": "综合", "conclusion": "允许自己迷茫一阵子（倒吊人），这是修复期不是摆烂期。建议每天只做一件让自己\"有点感觉\"的小事（散步、做饭、整理），星星牌的承诺是——方向会在你恢复感知的过程中自己浮现。", "id": "c10", "question": "工作和生活都提不起劲，不知道自己到底想要什么，该怎么办？", "scan": "全大牌——这是人生阶段课题，不是\"换个爱好\"能解决的；但牌序是低谷→悬置→星星，方向是向上的。", "source": "练习案例 · 虚构示意", "spread_id": "s3", "steps": ["过去 · 命运之轮逆：你刚从一段低谷里出来——运气、机会、状态都掉过，现在是冬天的尾巴，不是你\"废了\"。", "现在 · 倒吊人：别急着\"振作起来\"——倒吊人说，现在最好的姿势就是悬着：少做决定，多观察，把视角倒过来看看自己到底在为什么累。", "未来 · 星星：星星在终点等着——风雨后的宁静会回来，但星星只照给\"熬过黑夜\"的人，急不来。"], "title": "迷茫期：下一步往哪走"}];
const MINDMAP={"root": {"title": "塔罗全景", "note": "一张图收下整副牌：它是什么、怎么占、怎么解、怎么学", "children": [{"id": "A", "color": "#e8c66a", "title": "一、这副牌是什么 · 骨架", "note": "先认结构，再认单张", "children": [{"title": "78 张 = 22 大牌 + 56 小牌", "note": "大牌多＝分量重、周期长；小牌多＝日常操作层", "link": {"type": "guide", "anchor": "g1"}}, {"title": "大阿卡纳 · 人生课题线", "children": [{"title": "0 愚人 → 21 世界：一条成长弧", "link": {"type": "theme", "id": "t6"}}, {"title": "三段：1–7 身（显意识）/ 8–14 心（潜意识）/ 15–21 灵（超意识）"}, {"title": "编号即信息：越靠前越向外学，越靠后越向内修"}]}, {"title": "小阿卡纳 · 日常层", "children": [{"title": "四花色 = 四个领域", "link": {"type": "theme", "id": "t5"}, "children": [{"title": "权杖 · 火 — 行动、热情、事业"}, {"title": "圣杯 · 水 — 感情、关系、感受"}, {"title": "宝剑 · 风 — 思考、沟通、冲突"}, {"title": "星币 · 土 — 金钱、工作、身体"}]}, {"title": "数字 1–10 = 一件事的进程弧", "link": {"type": "theme", "id": "t7"}, "children": [{"title": "1 种子 → 2 选择 → 3 初长 → 4 稳定 → 5 冲突"}, {"title": "6 调和 → 7 考验 → 8 加速 → 9 临门 → 10 完成与溢出"}]}, {"title": "宫廷 16 = 牌里的人", "link": {"type": "theme", "id": "t8"}, "children": [{"title": "角色成长线：侍从 → 骑士 → 王后 → 国王"}, {"title": "性格配方：角色 × 花色元素"}]}]}, {"title": "★ 牌义生成公式", "note": "全图最核心的一条：牌义不是背出来的，是拼出来的", "children": [{"title": "小牌牌义 = 领域（花色）× 阶段（数字）"}, {"title": "宫廷牌义 = 角色 × 元素"}, {"title": "大牌牌义 = 原型课题 ＋ 在旅程中的位置"}]}]}, {"id": "B", "color": "#7fd4c1", "title": "二、一次占卜怎么做 · 流程", "note": "从提问到收尾的七步", "children": [{"title": "1 问对问题", "link": {"type": "theme", "id": "t9"}, "children": [{"title": "开放式，不问是非与宿命"}, {"title": "给时间窗，问“我能做什么”"}]}, {"title": "2 选牌阵", "note": "问题是什么结构，就选什么结构的牌阵", "link": {"type": "tab", "id": "spreads"}}, {"title": "3 抽牌摆牌", "note": "专注于问题，正逆随机出现"}, {"title": "4 先扫结构", "link": {"type": "theme", "id": "t17"}, "children": [{"title": "大牌比例 → 事情的分量"}, {"title": "花色配比 → 能量在哪个领域"}, {"title": "逆位比例 → 能量通不通"}, {"title": "重复数字/主题 → 被强调的信号"}]}, {"title": "5 逐张解", "note": "牌位义 × 这张牌的牌义 × 正逆位状态", "link": {"type": "theme", "id": "t1"}}, {"title": "6 串成故事", "note": "找因果线：主角是谁、转折在哪、往哪走"}, {"title": "7 给建议收尾", "note": "给方向不给命令，决定权在问卜者", "link": {"type": "theme", "id": "t16"}}]}, {"id": "C", "color": "#8fb8ff", "title": "三、解牌的逻辑 · 方法", "note": "牌义之上，还有一层“怎么读”的规矩", "children": [{"title": "三层牌义", "link": {"type": "theme", "id": "t1"}, "children": [{"title": "共通义 — 走到哪都认的骨"}, {"title": "理论义 — 元素/星座/数字推出来的根"}, {"title": "情境义 — 落到这个人的处境里"}]}, {"title": "元素分析", "note": "配比和缺席都说话：哪种能量多、哪种缺位", "link": {"type": "theme", "id": "t5"}}, {"title": "正逆位 = 能量状态", "link": {"type": "theme", "id": "t3"}, "children": [{"title": "正位 — 顺畅地流"}, {"title": "逆位 — 受阻 / 过度 / 转向内里（九式逐一排查）"}]}, {"title": "呼应与重复", "note": "同数字、同花色、同主题反复出现 = 牌在敲黑板"}, {"title": "学理 vs 直觉", "note": "先学理打底；直觉是学理熟透之后的速度，不是捷径", "link": {"type": "theme", "id": "t15"}}]}, {"id": "D", "color": "#d49ae8", "title": "四、学习怎么走 · 路径", "note": "顺序和导览一致：先地图，后细节", "children": [{"title": "导览六站 → 大牌 → 数字 → 宫廷 → 进阶主题 → 牌阵实战", "link": {"type": "tab", "id": "path"}}, {"title": "记忆靠钩子与规律，不靠死背", "link": {"type": "theme", "id": "t2"}}, {"title": "时间问题有专门打法", "link": {"type": "theme", "id": "t13"}}, {"title": "节奏：每日一牌＋单元打勾，学不完顺延不补课"}]}, {"id": "E", "color": "#e8a09a", "title": "五、心法与边界 · 根", "note": "技术之外，决定一位解牌者成色的部分", "children": [{"title": "咨询配比：疗愈 80% / 建议 20%", "link": {"type": "theme", "id": "t16"}}, {"title": "不断生死、不替人做决定、不说绝对化的话"}, {"title": "给自己占容易当局者迷 — 重要问题找人互占"}]}]}};
